// A quantity: 0 unless it is made of digits only.
fn qty_of(s: Str) -> Int {
  if s.is_empty() {
    return 0
  }
  for c in s.codes() {
    if c < 48 or c > 57 {
      return 0
    }
  }
  return s.to_int().unwrap_or(0)
}

// "item:qty" as a pair, or None when malformed.
fn parse_item(text: Str) -> Option[Pair[Str, Int]] {
  let parts = text.split(":")
  if parts.len() != 2 {
    return None
  }
  let name = parts.get_or(0, "")
  let qty = qty_of(parts.get_or(1, ""))
  if name.is_empty() or qty <= 0 {
    return None
  }
  return Some(Pair { first: name, second: qty })
}

// The items of an order "ID item:qty,item:qty", or None when malformed.
fn parse_items(order: Str) -> Option[List[Pair[Str, Int]]] {
  let parts = order.split(" ")
  if parts.len() != 2 or parts.get_or(0, "").is_empty() {
    return None
  }
  var items: List[Pair[Str, Int]] = []
  for text in parts.get_or(1, "").split(",") {
    let item = parse_item(text)
    if item.is_none() {
      return None
    }
    items = items.push(item.unwrap_or(Pair { first: "", second: 0 }))
  }
  return Some(items)
}

pub fn inventory(orders: List[Str], stock: Map[Str, Int]) -> Result[List[Str], Str] {
  var left: Map[Str, Int] = stock
  var filled: List[Str] = []
  for order in orders {
    let id = order.split(" ").get_or(0, "")
    let parsed = parse_items(order)
    if parsed.is_none() {
      return Err("bad order " + id)
    }
    let wanted = parsed.unwrap_or([])
    var known = true
    for entry in wanted {
      if left.has(entry.first) == false {
        known = false
      }
    }
    if known == false {
      return Err("bad order " + id)
    }
    var trial = left
    var enough = true
    for entry in wanted {
      let have = trial.get(entry.first).unwrap_or(0)
      if have < entry.second {
        enough = false
      } else {
        trial = trial.set(entry.first, have - entry.second)
      }
    }
    if enough {
      left = trial
      filled = filled.push(id)
    }
  }
  return Ok(filled)
}
